const int VERTEX_COUNT = 32 * 3 + 5;

#define PI 3.14159
void initPoses(out vec2 poseA[VERTEX_COUNT], out vec2 poseB[VERTEX_COUNT])
{
    const int circleVertexCount = 32;
    float thetaStep = (2.0 * PI) / float(circleVertexCount);
    for(int i = 0; i < circleVertexCount; i++){
        float theta = float(i) * thetaStep;
        float cT = cos(theta);
        float sT = sin(theta);
        //Left Eye
        poseA[i].x = -0.5 + cT*0.2;
        poseA[i].y = 0.3 + sT*0.2;
        poseB[i].x = -0.5 + cT*0.2;
        poseB[i].y = 0.4;
        //Right Eye
        poseA[i+circleVertexCount].x = 0.5 + cT*0.2;
        poseA[i+circleVertexCount].y = 0.3 + sT*0.2;
        poseB[i+circleVertexCount].x = 0.5 + cT*0.2;
        poseB[i+circleVertexCount].y = 0.4;
        //Mouth
        poseA[i+circleVertexCount*2].x = cT*0.5;
        poseA[i+circleVertexCount*2].y = -0.2;
        poseB[i+circleVertexCount*2].x = cT*0.3;
        poseB[i+circleVertexCount*2].y = -0.2 + sT*0.5;
    }

    //Right pupil
    poseA[VERTEX_COUNT-4].x = 0.5;
    poseA[VERTEX_COUNT-4].y = 0.3;
    poseB[VERTEX_COUNT-4].x = 0.5;
    poseB[VERTEX_COUNT-4].y = 0.4;

    //Left pupil
    poseA[VERTEX_COUNT-5].x = -0.5;
    poseA[VERTEX_COUNT-5].y = 0.3;
    poseB[VERTEX_COUNT-5].x = -0.5;
    poseB[VERTEX_COUNT-5].y = 0.4;

    //Nose
    poseA[VERTEX_COUNT-1].x = 0.0;
    poseA[VERTEX_COUNT-1].y = -0.02;
    poseB[VERTEX_COUNT-1].x = 0.0;
    poseB[VERTEX_COUNT-1].y = 0.4;

    poseA[VERTEX_COUNT-2].x = -0.1;
    poseA[VERTEX_COUNT-2].y = 0.1;
    poseB[VERTEX_COUNT-2].x = -0.1;
    poseB[VERTEX_COUNT-2].y = 0.4;

    poseA[VERTEX_COUNT-3].x = 0.1;
    poseA[VERTEX_COUNT-3].y = 0.1;
    poseB[VERTEX_COUNT-3].x = 0.1;
    poseB[VERTEX_COUNT-3].y = 0.4;
}

float distSquared( vec2 A, vec2 B )
{
    vec2 C = A - B;
    return dot( C, C );
}

float metaBall(vec2 uv, vec2 center, float radius){
    float d= (radius * radius) / distSquared(uv,center);
    return min(d,1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 poseA[VERTEX_COUNT];
    vec2 poseB[VERTEX_COUNT];
    initPoses(poseA,poseB);

    vec2 uv = fragCoord/iResolution.xy;
    uv = uv * 2.0 - 1.0; //-1 to 1
    uv.x *= iResolution.x / iResolution.y;

    //Background effect
    float d = length(uv) + sin(atan(uv.y,uv.x)*12.0+iTime*2.0)*0.05 - iTime * 0.2;
    d = mod(d,1.0);
    d = sin(d * 6.28)*0.5 + 0.5;

    vec3 col = vec3(d*0.3,d*0.3+0.1,d*0.3+0.5);

    //Animated time value (0-1)
    float t;
    if (iMouse.z > 0.0)
        t = iMouse.y / iResolution.y;
    else{
        t = mod(iTime,1.0);
        t = 1.0 - pow(t * 2.0 - 1.0,2.0);
        t = t + sin(t*64.0) * 0.01 * t;
    }
    vec2 p = uv;

    //Wobble
    p-=vec2(0.0,-.5);
    float a = cos(iTime) * 0.5;
    p *= mat2(cos(a),sin(a),-sin(a),cos(a));
    p+=vec2(0.0,-.5);
    p/=0.8 + sin(iTime)*0.2;

    //Draw metaballs at each "vertex"
    float total = 0.0;
    for(int i = 0; i < VERTEX_COUNT; i++){
        vec2 v = mix(poseA[i],poseB[i],t);
        float inf = metaBall(p,v,0.02);
        total+=inf;
    }
    col+=smoothstep(1.0,1.02,total);
    col+=vec3(total*0.7,total*0.3,total*0.5);//Glow
    // Output to screen
    fragColor = vec4(col,1.0);
}
